use chrono::{Local, SecondsFormat};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use super::block::{ContentBlock, TextBlock, ToolResultBlock, ToolUseBlock};
use super::usage::ChatUsage;
use super::JsonMap;

/// The role of a message participant in agent conversations.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum MsgRole {
    User,
    Assistant,
    System,
    Tool,
}

/// The reason why a message was generated by an agent.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum GenerateReason {
    /// Model stopped normally, task completed.
    ModelStop,
    /// Model returned tool calls (internal tools, framework continues execution).
    ToolCalls,
    /// Structured output completed.
    StructuredOutput,
    /// Tool execution was suspended, waiting for user results.
    ToolSuspended,
    /// Reasoning phase was stopped by a hook.
    ReasoningStopRequested,
    /// Acting phase was stopped by a hook.
    ActingStopRequested,
    /// Permission engine is asking the user to confirm one or more tool calls.
    PermissionAsking,
    /// A middleware requested the agent to pause via `RequestStopEvent`.
    MiddlewareStopRequested,
    /// All tool calls were denied by the user and a hook requested the agent to stop.
    AllToolsDenied,
    /// Agent was interrupted.
    Interrupted,
    /// Maximum iterations reached.
    MaxIterations,
    /// A `returnDirect` tool's result was returned directly to the caller as the
    /// turn's final answer, skipping the follow-up model call.
    ToolReturnDirect,
}

/// Timestamp format `yyyy-MM-dd HH:mm:ss.SSS` in the system's default time zone,
/// mirroring the Java SDK.
pub fn current_timestamp() -> String {
    Local::now().to_rfc3339_opts(SecondsFormat::Millis, false).replace('T', " ")
}

fn generate_id() -> String {
    Uuid::new_v4().to_string()
}

/// A message in the AgentScope framework.
///
/// Messages are the primary communication unit between agents, users, and tools. Each message
/// has a role, content blocks, and optional metadata. The role determines which content blocks
/// are allowed, mirroring `Msg` validation in the Java SDK.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Msg {
    /// Unique identifier for the message.
    pub id: String,
    /// Optional name for the message.
    pub name: Option<String>,
    /// Role of the message sender.
    pub role: MsgRole,
    /// Content blocks that make up the message content.
    pub content: Vec<ContentBlock>,
    /// Additional metadata. Never null; defaults to an empty map.
    pub metadata: JsonMap,
    /// Timestamp in `yyyy-MM-dd HH:mm:ss.SSS` format.
    pub timestamp: String,
    /// Token usage from the model call that produced this message.
    pub usage: Option<ChatUsage>,
}

impl Msg {
    /// Metadata key for the generate reason.
    pub const METADATA_GENERATE_REASON: &'static str = "agentscope_generate_reason";
    /// Metadata key for carrying confirm results when resuming a permission HITL pause.
    pub const METADATA_CONFIRM_RESULTS: &'static str = "agentscope_confirm_results";
    /// Metadata key (bool) marking a message as synthetic.
    pub const METADATA_SYNTHETIC: &'static str = "agentscope_synthetic";
    /// Metadata key (string) describing the kind of synthetic reminder.
    pub const METADATA_REMINDER_KIND: &'static str = "agentscope_reminder_kind";

    /// Creates a new message with a randomly generated ID and the current timestamp.
    pub fn new(
        id: impl Into<String>,
        name: Option<String>,
        role: MsgRole,
        content: Vec<ContentBlock>,
        metadata: Option<JsonMap>,
        timestamp: Option<String>,
        usage: Option<ChatUsage>,
    ) -> Self {
        let metadata = match metadata {
            Some(m) => m
                .into_iter()
                .filter(|(k, v)| !k.is_empty() && !v.is_null())
                .collect(),
            None => JsonMap::new(),
        };

        let msg = Msg {
            id: id.into(),
            name,
            role,
            content,
            metadata,
            timestamp: timestamp.unwrap_or_else(current_timestamp),
            usage,
        };
        validate_role_content(&msg.role, &msg.content);
        msg
    }

    /// Creates a `Msg` with the given role from a text string.
    pub fn text(role: MsgRole, text: impl Into<String>) -> Self {
        Self::builder()
            .role(role)
            .text_content(text)
            .build()
    }

    /// Creates a user message from a text string.
    pub fn user(text: impl Into<String>) -> Self {
        Self::text(MsgRole::User, text)
    }

    /// Creates a user message from content blocks.
    pub fn user_blocks(blocks: Vec<ContentBlock>) -> Self {
        Self::builder().role(MsgRole::User).content(blocks).build()
    }

    /// Creates an assistant message from a text string.
    pub fn assistant(text: impl Into<String>) -> Self {
        Self::text(MsgRole::Assistant, text)
    }

    /// Creates an assistant message from content blocks.
    pub fn assistant_blocks(blocks: Vec<ContentBlock>) -> Self {
        Self::builder()
            .role(MsgRole::Assistant)
            .content(blocks)
            .build()
    }

    /// Creates a system message from a text string.
    pub fn system(text: impl Into<String>) -> Self {
        Self::text(MsgRole::System, text)
    }

    /// Creates a tool message carrying a single tool result.
    pub fn tool(tool_call_id: &str, tool_name: &str, result_text: impl Into<String>) -> Self {
        Self::builder()
            .role(MsgRole::Tool)
            .content(vec![ContentBlock::ToolResult(ToolResultBlock::new(
                tool_call_id,
                tool_name,
                vec![ContentBlock::Text(TextBlock::new(result_text))],
            ))])
            .build()
    }

    /// Creates a tool message from tool result blocks.
    pub fn tool_blocks(results: Vec<ToolResultBlock>) -> Self {
        Self::builder()
            .role(MsgRole::Tool)
            .content(results.into_iter().map(ContentBlock::ToolResult).collect())
            .build()
    }

    /// Returns the role-appropriate builder, or the base builder for `None`.
    pub fn builder_for_role(role: Option<MsgRole>) -> MsgBuilder {
        match role {
            Some(MsgRole::User) => Self::builder().role(MsgRole::User),
            Some(MsgRole::Assistant) => Self::builder().role(MsgRole::Assistant),
            Some(MsgRole::System) => Self::builder().role(MsgRole::System),
            Some(MsgRole::Tool) => Self::builder().role(MsgRole::Tool),
            None => Self::builder(),
        }
    }

    /// Creates a new message builder with a randomly generated ID.
    pub fn builder() -> MsgBuilder {
        MsgBuilder::new()
    }

    /// The unique identifier of this message.
    pub fn id(&self) -> &str {
        &self.id
    }

    /// The optional name of this message.
    pub fn name(&self) -> Option<&str> {
        self.name.as_deref()
    }

    /// The role of the message sender.
    pub fn role(&self) -> MsgRole {
        self.role
    }

    /// The immutable list of content blocks.
    pub fn content(&self) -> &[ContentBlock] {
        &self.content
    }

    /// The metadata associated with this message.
    pub fn metadata(&self) -> &JsonMap {
        &self.metadata
    }

    /// The timestamp of this message.
    pub fn timestamp(&self) -> &str {
        &self.timestamp
    }

    /// The token usage information associated with this message.
    pub fn usage(&self) -> Option<&ChatUsage> {
        self.usage.as_ref()
    }

    /// Whether this message has content blocks of the given variant.
    pub fn has_block(&self, kind: ContentBlockKind) -> bool {
        self.content.iter().any(|b| kind.matches(b))
    }

    /// Returns all content blocks matching the given variant.
    pub fn blocks(&self, kind: ContentBlockKind) -> Vec<&ContentBlock> {
        self.content.iter().filter(|b| kind.matches(b)).collect()
    }

    /// Returns the first content block, or `None` if empty.
    pub fn first_content_block(&self) -> Option<&ContentBlock> {
        self.content.first()
    }

    /// Returns the first content block of the given variant.
    pub fn first_block(&self, kind: ContentBlockKind) -> Option<&ContentBlock> {
        self.content.iter().find(|b| kind.matches(b))
    }

    /// Whether this message contains structured data in its metadata.
    pub fn has_structured_data(&self) -> bool {
        self.metadata.contains_key(super::keys::metadata_keys::STRUCTURED_OUTPUT)
    }

    /// Returns the structured output value as a raw JSON value.
    pub fn structured_data(&self) -> Option<&serde_json::Value> {
        self.metadata
            .get(super::keys::metadata_keys::STRUCTURED_OUTPUT)
    }

    /// Extracts plain text content, joining all text blocks with newlines.
    pub fn text_content(&self) -> String {
        self.content
            .iter()
            .filter_map(|b| match b {
                ContentBlock::Text(t) => Some(t.text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// Returns all `ToolUseBlock`s in this message.
    pub fn tool_use_blocks(&self) -> impl Iterator<Item = &ToolUseBlock> {
        self.content.iter().filter_map(|b| match b {
            ContentBlock::ToolUse(t) => Some(t),
            _ => None,
        })
    }

    /// Returns all `ToolResultBlock`s in this message.
    pub fn tool_result_blocks(&self) -> impl Iterator<Item = &ToolResultBlock> {
        self.content.iter().filter_map(|b| match b {
            ContentBlock::ToolResult(t) => Some(t),
            _ => None,
        })
    }

    /// Returns the accumulated chat usage, either from the `usage` field or from the
    /// `_chat_usage` metadata entry (parsed without caching).
    pub fn chat_usage(&self) -> Option<ChatUsage> {
        if let Some(usage) = &self.usage {
            return Some(*usage);
        }
        self.metadata
            .get(super::keys::metadata_keys::CHAT_USAGE)
            .and_then(|v| serde_json::from_value(v.clone()).ok())
    }

    /// The reason this message was generated, defaulting to `ModelStop`.
    pub fn generate_reason(&self) -> GenerateReason {
        self.metadata
            .get(Self::METADATA_GENERATE_REASON)
            .and_then(|v| serde_json::from_value(v.clone()).ok())
            .unwrap_or(GenerateReason::ModelStop)
    }

    /// Returns a new `Msg` with the given generate reason stored in metadata.
    pub fn with_generate_reason(&self, reason: GenerateReason) -> Self {
        let mut new_metadata = self.metadata.clone();
        new_metadata.insert(
            Self::METADATA_GENERATE_REASON.to_string(),
            serde_json::to_value(reason).expect("GenerateReason is always serializable"),
        );
        let mut msg = self.clone();
        msg.metadata = new_metadata;
        msg
    }

    /// Returns a copy of this message with the given content blocks.
    pub fn with_content(&self, new_content: Vec<ContentBlock>) -> Self {
        let mut msg = self.clone();
        msg.content = new_content;
        msg
    }

    /// Returns a copy of this message with structured output data stored in metadata.
    pub fn with_structured_data(&self, value: serde_json::Value) -> Self {
        let mut new_metadata = self.metadata.clone();
        new_metadata.insert(
            super::keys::metadata_keys::STRUCTURED_OUTPUT.to_string(),
            value,
        );
        let mut msg = self.clone();
        msg.metadata = new_metadata;
        msg
    }
}

/// Validates that the content blocks are compatible with the message role.
fn validate_role_content(role: &MsgRole, content: &[ContentBlock]) {
    match role {
        MsgRole::User => {
            for block in content {
                match block {
                    ContentBlock::Text(_)
                    | ContentBlock::Data(_)
                    | ContentBlock::Image(_)
                    | ContentBlock::Audio(_)
                    | ContentBlock::Video(_) => {}
                    other => panic!(
                        "USER message may only contain text/data/image/audio/video blocks, got {}",
                        block_variant_name(other)
                    ),
                }
            }
        }
        MsgRole::System => {
            for block in content {
                if !matches!(block, ContentBlock::Text(_)) {
                    panic!(
                        "SYSTEM message may only contain text blocks, got {}",
                        block_variant_name(block)
                    );
                }
            }
        }
        MsgRole::Assistant | MsgRole::Tool => {}
    }
}

fn block_variant_name(block: &ContentBlock) -> &'static str {
    match block {
        ContentBlock::Text(_) => "text",
        ContentBlock::Thinking(_) => "thinking",
        ContentBlock::Image(_) => "image",
        ContentBlock::Audio(_) => "audio",
        ContentBlock::Video(_) => "video",
        ContentBlock::ToolUse(_) => "tool_use",
        ContentBlock::ToolResult(_) => "tool_result",
        ContentBlock::Hint(_) => "hint",
        ContentBlock::Data(_) => "data",
    }
}

/// Kind of content block used to filter message content.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ContentBlockKind {
    Text,
    Thinking,
    Image,
    Audio,
    Video,
    ToolUse,
    ToolResult,
    Hint,
    Data,
}

impl ContentBlockKind {
    fn matches(&self, block: &ContentBlock) -> bool {
        matches!(
            (self, block),
            (ContentBlockKind::Text, ContentBlock::Text(_))
                | (ContentBlockKind::Thinking, ContentBlock::Thinking(_))
                | (ContentBlockKind::Image, ContentBlock::Image(_))
                | (ContentBlockKind::Audio, ContentBlock::Audio(_))
                | (ContentBlockKind::Video, ContentBlock::Video(_))
                | (ContentBlockKind::ToolUse, ContentBlock::ToolUse(_))
                | (ContentBlockKind::ToolResult, ContentBlock::ToolResult(_))
                | (ContentBlockKind::Hint, ContentBlock::Hint(_))
                | (ContentBlockKind::Data, ContentBlock::Data(_))
        )
    }
}

/// Fluent builder for `Msg`.
#[derive(Debug, Clone)]
pub struct MsgBuilder {
    id: String,
    name: Option<String>,
    role: MsgRole,
    content: Vec<ContentBlock>,
    metadata: JsonMap,
    timestamp: String,
    usage: Option<ChatUsage>,
}

impl Default for MsgBuilder {
    fn default() -> Self {
        Self::new()
    }
}

impl MsgBuilder {
    /// Creates a new builder with a randomly generated message ID.
    pub fn new() -> Self {
        Self {
            id: generate_id(),
            name: None,
            role: MsgRole::User,
            content: Vec::new(),
            metadata: JsonMap::new(),
            timestamp: current_timestamp(),
            usage: None,
        }
    }

    /// Sets the unique identifier for the message.
    pub fn id(mut self, id: impl Into<String>) -> Self {
        self.id = id.into();
        self
    }

    /// Sets the optional name for the message.
    pub fn name(mut self, name: impl Into<String>) -> Self {
        self.name = Some(name.into());
        self
    }

    /// Sets the role for the message.
    pub fn role(mut self, role: MsgRole) -> Self {
        self.role = role;
        self
    }

    /// Sets content from a list of content blocks.
    pub fn content(mut self, content: Vec<ContentBlock>) -> Self {
        self.content = content;
        self
    }

    /// Sets content from a single content block.
    pub fn block(mut self, block: ContentBlock) -> Self {
        self.content = vec![block];
        self
    }

    /// Sets text content from a string.
    pub fn text_content(mut self, text: impl Into<String>) -> Self {
        self.content = vec![ContentBlock::Text(TextBlock::new(text))];
        self
    }

    /// Sets metadata.
    pub fn metadata(mut self, metadata: JsonMap) -> Self {
        self.metadata = metadata;
        self
    }

    /// Inserts a single metadata key/value.
    pub fn metadata_entry(mut self, key: impl Into<String>, value: serde_json::Value) -> Self {
        self.metadata.insert(key.into(), value);
        self
    }

    /// Sets the timestamp for the message.
    pub fn timestamp(mut self, timestamp: impl Into<String>) -> Self {
        self.timestamp = timestamp.into();
        self
    }

    /// Sets the token usage information for this message.
    pub fn usage(mut self, usage: ChatUsage) -> Self {
        self.usage = Some(usage);
        self
    }

    /// Sets the generate reason for this message.
    pub fn generate_reason(mut self, reason: GenerateReason) -> Self {
        self.metadata.insert(
            Msg::METADATA_GENERATE_REASON.to_string(),
            serde_json::to_value(reason).expect("GenerateReason is always serializable"),
        );
        self
    }

    /// Builds the message with the configured properties.
    pub fn build(self) -> Msg {
        Msg::new(
            self.id,
            self.name,
            self.role,
            self.content,
            Some(self.metadata),
            Some(self.timestamp),
            self.usage,
        )
    }
}

impl std::fmt::Display for Msg {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.text_content())
    }
}
